// Controlled saved-news fixtures generated by the actual Python service. No live providers.
// Requires Playwright/Chrome, repository venv, and a running frontend (QA_BASE).
const {chromium}=require('playwright')
const {execFileSync}=require('node:child_process')
const assert=require('node:assert/strict')
const fs=require('node:fs')
const base=process.env.QA_BASE||'http://127.0.0.1:3000'
const out=process.env.ARTIFACT_DIR||'/tmp/stockscope-news'
fs.mkdirSync(out,{recursive:true})
const fixtures=JSON.parse(execFileSync('venv/bin/python',['scripts/news-fixtures.py'],{encoding:'utf8'}))
async function setup(browser,width,role) {
 const page=await browser.newPage({viewport:{width,height:900},serviceWorkers:'block',reducedMotion:'reduce'})
 page.setDefaultTimeout(15000);page.setDefaultNavigationTimeout(45000)
 await page.addInitScript(role=>sessionStorage.setItem('stockscope_session',JSON.stringify({user:{id:'news-'+role,name:'Test',role},role,expiresAt:Date.now()+3600000,accessToken:'fixture'})),role)
 const errors=[];page.on('pageerror',e=>errors.push(e.message))
 const state={fail:false,delayOldest:false,requests:[]}
 await page.route('https://**',r=>r.fulfill({status:404,body:''}))
 await page.route('**/api/**',async r=>{
  const url=new URL(r.request().url()),path=url.pathname
  let json=[],status=200
  if(path.endsWith('/news')) {
   const symbol=path.split('/')[3],sort=url.searchParams.get('sort')||'date-desc',offset=url.searchParams.get('offset')||'0'
   state.requests.push({symbol,sort,offset})
   if(state.delayOldest&&sort==='date-asc')await new Promise(resolve=>setTimeout(resolve,800))
   const key=[symbol,sort,offset,url.searchParams.getAll('exclude_source').sort().join(',')].join('|')
   assert.ok(fixtures[key],key)
   json={...fixtures[key],can_collect:['admin','member'].includes(role)}
   const limit=Number(url.searchParams.get('limit')||20);json.articles=json.articles.slice(0,limit);json.count=json.articles.length;json.limit=limit;json.has_more=json.offset+json.count<json.total
   if(state.fail){status=503;json={detail:'Controlled saved-news failure'}}
  } else if(path.endsWith('/status')){status=404;json={detail:'No refresh tracked'}}
  else if(path.endsWith('/stocks'))json={stocks:[]}
  else if(/^\/api\/stocks\/[^/]+$/.test(path))json={ticker:path.split('/')[3],sources:[],sentiment_metrics:{sample_size:0,avg_sentiment:null},filings:[]}
  await r.fulfill({status,json,headers:{'access-control-allow-origin':base,'access-control-allow-headers':'Authorization,Content-Type','access-control-allow-methods':'GET,POST,OPTIONS'}}).catch(()=>{})
 })
 return {page,state,errors}
}
async function collection(browser,width,role) {
 const {page,state,errors}=await setup(browser,width,role)
 await page.goto(base+'/stock/EMPTY?tab=news',{waitUntil:'networkidle'})
 const news=page.getByRole('region',{name:'Saved news',exact:true})
 await news.getByText('No saved news for EMPTY yet.',{exact:true}).waitFor()
 if(['admin','member'].includes(role)) {
  await news.getByRole('link',{name:'Open research summary',exact:true}).click()
  const action=page.getByRole('button',{name:'Refresh sources',exact:true});await action.waitFor();await page.waitForFunction(()=>[...document.querySelectorAll('button')].some(button=>button.textContent==='Refresh sources'&&!button.disabled));assert.ok(await action.isEnabled())
 } else {
  assert.equal(await news.getByRole('link',{name:/research summary/}).count(),0)
  assert.ok(!(await news.innerText()).includes('Open the research summary'))
  const link=news.getByRole('link',{name:'View company overview',exact:true});await link.waitFor();assert.equal(await link.getAttribute('href'),'/stock/EMPTY')
 }
 state.fail=true;await page.goto(base+'/stock/EMPTY?tab=news',{waitUntil:'networkidle'});await news.getByRole('alert').waitFor()
 assert.equal(await news.getByText('No saved news for EMPTY yet.',{exact:true}).count(),0)
 assert.equal(await news.getByRole('link',{name:'Open research summary',exact:true}).count(),0)
 state.fail=false;await news.getByRole('button',{name:'Retry saved news',exact:true}).click();await news.getByText('No saved news for EMPTY yet.',{exact:true}).waitFor()
 assert.deepEqual(errors,[]);await page.close();console.log(width,role,'empty guidance, collection destination, failure/retry PASS')
}
async function pagination(browser,width) {
 const {page,state,errors}=await setup(browser,width,'member')
 await page.goto(base+'/stock/AAPL?tab=news',{waitUntil:'networkidle'})
 const news=page.getByRole('region',{name:'Saved news',exact:true})
 const range=text=>news.getByText(text,{exact:false}).waitFor()
 const titles=()=>news.locator('article h3').allTextContents()
 const sort=async name=>{await news.getByRole('button',{name:'Sort',exact:true}).click();await news.getByRole('button',{name,exact:true}).click()}
 const source=async (name,on)=>{const box=news.getByRole('checkbox',{name,exact:true});if(!await box.isVisible())await news.getByRole('button',{name:/^Sources/}).click();if(await box.isChecked()!==on)await news.locator('label').filter({has:page.getByRole('checkbox',{name,exact:true})}).click()}
 await range('1–20 of 46 matching saved articles');const first=await titles()
 await news.getByRole('button',{name:'Next page',exact:true}).click();await range('21–40 of 46');const second=await titles()
 await news.getByRole('button',{name:'Next page',exact:true}).click();await range('41–46 of 46');const third=await titles()
 assert.equal(new Set([...first,...second,...third]).size,46)
 await source('Common source',false);await range('1–3 of 3 matching saved articles');assert.equal((await titles()).length,3);assert.equal(state.requests.at(-1).offset,'0')
 await source('Rare source',false);await news.getByText('No saved articles match the selected sources.',{exact:true}).waitFor()
 await page.keyboard.press('Escape');await news.getByRole('button',{name:'Clear source filters',exact:true}).click();await range('1–20 of 46')
 await sort('Oldest First');await news.getByRole('link',{name:'Article 00',exact:false}).waitFor();assert.match((await titles())[0],/Article 00/)
 await sort('Most Positive');await range('1–20 of 46');assert.match((await titles())[0],/Article 00/)
 await sort('Most Negative');await news.getByRole('link',{name:'Article 01',exact:false}).waitFor();assert.match((await titles())[0],/Article 01/)
 // A slower old selection must never replace the newest result/order.
 state.delayOldest=true;await sort('Oldest First');await sort('Latest First');await range('1–20 of 46');await page.waitForTimeout(1000);assert.deepEqual(await titles(),first)
 state.delayOldest=false;state.fail=true
 await news.getByRole('button',{name:'Next page',exact:true}).click();await news.getByRole('alert').waitFor()
 assert.equal(await news.getByText(/No saved (news|articles)/).count(),0)
 state.fail=false;await news.getByRole('button',{name:'Retry saved news',exact:true}).click();await range('21–40 of 46');assert.deepEqual(await titles(),second)
 await sort('Oldest First');await range('1–20 of 46');assert.equal(state.requests.at(-1).offset,'0')
 assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth && document.querySelector('main').scrollWidth<=document.querySelector('main').clientWidth+1))
 await page.screenshot({path:`${out}/news-${width}.png`});assert.deepEqual(errors,[])
 await page.close();console.log(width,'complete collection pages, source/tone sorting, ties, reset, stale requests and failure recovery PASS')
}
;(async()=>{const browser=await chromium.launch({channel:'chrome',headless:true});try {
 for(const width of [1440,320]) {
  await pagination(browser,width)
  for(const role of ['member','admin','viewer','guest','demo'])await collection(browser,width,role)
 }
}finally{await browser.close()}})().catch(error=>{console.error(error);process.exitCode=1})
